// Package syncsclient calls package syncs, whose synchronisation it learns from facts.
package syncsclient

import "syncs"

// Wait synchronises through syncs.Group.Wait, which it knows from that method's fact.
func Wait(g *syncs.Group) { g.Wait() } // want Wait:`^syncs$`

// Plain calls a function of syncs that does not synchronise.
func Plain() int { return syncs.Plain(1) }
